"""Publish the shared arsenal with current gameplay values and source artwork."""
from pathlib import Path
from html import escape
from build_realm_completion import REALMS,AIR,BEAST
ROOT=Path(__file__).resolve().parents[1]
labels={'h':'Humans','a':'Angels','d':'Hell','i':'Noetic Assembly','f':'Forsaken Host'}
effects={'h':'Nuclear missile: five-second warning, six-cell blast, damages allies and enemies.', 'a':'Witness of Salt: the angel unfolds three pairs of wings, flashes after five seconds, petrifies everything destructible within four cells, then the statues crumble four seconds later. Friendly fire applies.', 'd':'Hellrift: five-cell blast that burns enemy armies and structures.', 'i':'Extinction: three orbital pulses in five cells with combat-system disruption.', 'f':'Sepulchral Rapture: five-cell soul blast and thirty seconds of miracle suppression.'}
cards=[]
for p,(_,_,airname,beastname,powername,_,radius) in REALMS.items():
 items=[]
 for data,name,kind in [(AIR[p],airname,'Aircraft'),(BEAST[p],beastname,'Beast')]:
  suffix,hp,speed,cost,damage,reload=data
  items.append(f'<article><img src="assets/realm-completion/{p}_{suffix}.webp" alt="{escape(name)}"><h3>{name}</h3><p>{kind} · Cost {cost} · HP {hp:,} · Speed {speed}</p><p>Base damage {damage:,}; reload {reload} ticks. Armor and faction modifiers apply.</p></article>')
 image='assets/roster/h-tech.webp' if p=='h' else f'assets/realm-completion/{p}_cataclysm.webp'
 items.append(f'<article><img src="{image}" alt="{powername}"><h3>{powername}</h3><p>{effects[p]}</p><p>Cost 6000 · 250 power · five-minute recharge · one per player.</p>'+('<p>The human installation currently uses existing tech-building artwork.</p>' if p=='h' else '')+'</article>')
 cards.append(f'<section><h2>{labels[p]}</h2><p>Shared by all four subfactions. Existing faction buildings and defensive structures remain available.</p><div class="grid">'+''.join(items)+'</div></section>')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sevenfall — Shared Arsenal</title><style>body{margin:0;background:#11151d;color:#edf0f4;font:17px/1.6 system-ui}main{max-width:1150px;margin:auto;padding:32px 20px}a{color:#8de8ed}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:20px}article{background:#202735;border:1px solid #3c485c;padding:20px;border-radius:8px}img{width:100%;height:220px;object-fit:contain}h1{font-size:44px}section{margin:36px 0}small{color:#bdc5d0}</style></head><body><main><nav><a href="index.html">Home</a> · <a href="new-realms.html">New realms</a> · <a href="forces.html">Released field guide</a></nav><h1>Five realms. Five shared arsenals.</h1><p>Development content for all twenty subfactions: aircraft, beasts and parent-faction superweapons, alongside existing buildings and defenses. Published alpha.2 downloads are unchanged.</p><p>Destroy or depower an installation during its warning to cancel the strike. Once salt judgement lands, destroying its source cannot rescue the statues. Terrain tiles and resources are not transformed.</p>'''+''.join(cards)+'''<section><h2>Witness of Salt</h2><img style="height:400px" src="assets/realm-completion/sf_witness.webp" alt="Six-winged Witness of Salt"><p>Three wing pairs unfold before the flash. Petrified actors stop moving, lose weapon damage and become salt-white. Buildings lose power and production pauses before the four-second crumble.</p></section><small>Twenty new generated sprite sheets; initial two-pose movement/attack cycles and held wrecks. Further animation, sound, balance and multiplayer acceptance remain development work.</small></main></body></html>'''
(ROOT/'docs/arsenal.html').write_text(page,encoding='utf8')
